function editKey(i,key){const s=labs[i];if(!s.edit||s.variant!=='c')return;const at=s.bar*16+s.step,m=(key[0]==='u'?upperMidi:naturalMidi)[Number(key.slice(1))]-(s.track===3?12:0);let e=s.events.find(e=>e.t===s.track&&e.at===at);if(!e){e={t:s.track,at,len:Math.min(4,16-s.step),notes:[]};s.events.push(e);}if(e.notes.includes(m))e.notes=e.notes.filter(x=>x!==m);else e.notes.push(m);e.notes.sort((a,b)=>a-b);if(!e.notes.length)s.events=s.events.filter(x=>x!==e);saveIdea(i);}
